"use client";

import { useId } from "react";
import { Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

export type HighlightShape = "rect" | "circle";

export interface RectTarget {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface CircleTarget {
  cx: number;
  cy: number;
  r: number;
}

export interface HighlightRingProps {
  /** Which target geometry to ring. */
  shape?: HighlightShape;
  /** Rect target — object or a "x, y, w, h" string (composition-space px). */
  rect?: RectTarget | string;
  /** Circle target — object or a "cx, cy, r" string (composition-space px). */
  circle?: CircleTarget | string;
  /** Corner radius of the rect ring. Clamped to half the shorter side. */
  radius?: number;
  strokeWidth?: number;
  /** Ring stroke color. */
  color?: string;
  /** Gap (px) between the target's edge and the ring. */
  padding?: number;
  /** Frames the stroke-draw takes (ease-out). */
  drawDuration?: number;
  /** One subtle 1.03 scale pulse right after the draw completes. No loop. */
  pulse?: boolean;
  /** Feathered scrim everywhere except the target, fading in with the draw. */
  dimOutside?: boolean;
  /** Scrim fill. */
  dimColor?: string;
  /** Feather (px) on the scrim's cut-out edge. */
  dimFeather?: number;
  /** Composition frame at which the ring starts drawing. */
  enterAt?: number;
  /** Composition frame at which the overlay starts fading out. 0 = never. */
  exitAt?: number;
  speed?: number;
  /** Renders the built-in Acme settings screen behind the ring (preview). */
  showDemoUi?: boolean;
  className?: string;
}

const FONT_FAMILY =
  'Inter, var(--font-geist-sans), -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';

/** Frames the exit fade takes once `exitAt` is reached. */
export const EXIT_FADE_FRAMES = 10;

/**
 * Default targets match the built-in Acme settings demo UI (1280x720):
 * the "Upgrade" button in the workspace-plan card.
 */
export const DEFAULT_RECT: RectTarget = { x: 1088, y: 178, w: 128, h: 40 };
export const DEFAULT_CIRCLE: CircleTarget = { cx: 1152, cy: 198, r: 72 };

/** "12, 34 56" → [12, 34, 56]. Drops anything that isn't a finite number. */
export function parseNumberList(value: string): number[] {
  return value
    .split(/[,\s]+/)
    .map((part) => Number.parseFloat(part))
    .filter((n) => Number.isFinite(n));
}

/** Accepts a RectTarget or a "x, y, w, h" string; invalid input → fallback. */
export function parseRect(
  value: RectTarget | string | undefined,
  fallback: RectTarget,
): RectTarget {
  if (value === undefined) return fallback;
  if (typeof value !== "string") {
    const ok = [value.x, value.y, value.w, value.h].every(Number.isFinite);
    return ok ? value : fallback;
  }
  const nums = parseNumberList(value);
  if (nums.length < 4) return fallback;
  return { x: nums[0], y: nums[1], w: nums[2], h: nums[3] };
}

/** Accepts a CircleTarget or a "cx, cy, r" string; invalid input → fallback. */
export function parseCircle(
  value: CircleTarget | string | undefined,
  fallback: CircleTarget,
): CircleTarget {
  if (value === undefined) return fallback;
  if (typeof value !== "string") {
    const ok = [value.cx, value.cy, value.r].every(Number.isFinite);
    return ok ? value : fallback;
  }
  const nums = parseNumberList(value);
  if (nums.length < 3) return fallback;
  return { cx: nums[0], cy: nums[1], r: nums[2] };
}

/** Corner radius clamped so opposite corners never overlap. */
export function clampCornerRadius(
  radius: number,
  w: number,
  h: number,
): number {
  return Math.max(0, Math.min(radius, Math.min(w, h) / 2));
}

/** Perimeter of a rounded rectangle (drives the stroke-dash draw). */
export function roundedRectPerimeter(
  w: number,
  h: number,
  radius: number,
): number {
  const r = clampCornerRadius(radius, w, h);
  return 2 * (w + h) - 8 * r + 2 * Math.PI * r;
}

/** Circumference of a circle (drives the stroke-dash draw). */
export function circlePerimeter(r: number): number {
  return 2 * Math.PI * Math.max(0, r);
}

const PLAN_ROWS: Array<{ name: string; email: string; role: string }> = [
  { name: "Dana Ships", email: "dana@acme.dev", role: "Owner" },
  { name: "Marta Gale", email: "marta@acme.dev", role: "Admin" },
  { name: "Lee Vandelay", email: "lee@acme.dev", role: "Member" },
];

/**
 * Static light Acme settings screen for the preview — the default rect target
 * is the "Upgrade" button in the workspace-plan card. 1280x720 coordinates.
 */
function AcmeSettingsDemo() {
