      style={{
        position: "absolute",
        inset: 0,
        background: "#FAFAFA",
        fontFamily: FONT_FAMILY,
        color: "#101828",
      }}
    >
      {/* Top bar */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: 64,
          background: "#FFFFFF",
          borderBottom: "1px solid #E4E7EC",
          display: "flex",
          alignItems: "center",
          padding: "0 40px",
        }}
      >
        <div
          style={{
            width: 26,
            height: 26,
            borderRadius: 7,
            background: "#101828",
            color: "#FFFFFF",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 14,
            fontWeight: 700,
          }}
        >
          A
        </div>
        <span
          style={{
            marginLeft: 10,
            fontSize: 15,
            fontWeight: 600,
            letterSpacing: "-0.01em",
          }}
        >
          Acme
        </span>
        <span style={{ marginLeft: 24, fontSize: 14, color: "#667085" }}>
          Dashboard
        </span>
        <span style={{ marginLeft: 20, fontSize: 14, fontWeight: 500 }}>
          Settings
        </span>
        <div
          style={{
            marginLeft: "auto",
            width: 30,
            height: 30,
            borderRadius: 999,
            background: "#E4E7EC",
            color: "#667085",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 12,
            fontWeight: 600,
          }}
        >
          DS
        </div>
      </div>

      {/* Heading */}
      <div
        style={{
          position: "absolute",
          left: 40,
          top: 92,
          fontSize: 22,
          fontWeight: 600,
          letterSpacing: "-0.02em",
        }}
      >
        Settings
      </div>

      {/* Workspace-plan card — the Upgrade button is the default ring target */}
      <div
        style={{
          position: "absolute",
          left: 40,
          top: 140,
          width: 1200,
          height: 116,
          background: "#FFFFFF",
          border: "1px solid #E4E7EC",
