        </div>
        <div style={{ marginTop: 6, fontSize: 13, color: "#667085" }}>
          Free — 3 of 3 seats used · 2 GB storage
        </div>
        {/* Upgrade button at (1088, 178, 128, 40) in composition space */}
        <div
          style={{
            position: "absolute",
            right: 24,
            top: 38,
            width: 128,
            height: 40,
            borderRadius: 8,
            background: "#266DF0",
            color: "#FFFFFF",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 14,
            fontWeight: 500,
          }}
        >
          Upgrade
        </div>
      </div>

      {/* Members card */}
      <div
        style={{
          position: "absolute",
          left: 40,
          top: 280,
          width: 1200,
          background: "#FFFFFF",
          border: "1px solid #E4E7EC",
          borderRadius: 10,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            height: 48,
