            }}
          >
            <span style={{ width: 260, fontWeight: 500 }}>{row.name}</span>
            <span style={{ width: 320, color: "#667085" }}>{row.email}</span>
            <span
              style={{
                marginLeft: "auto",
                padding: "3px 10px",
                borderRadius: 999,
                fontSize: 12,
                fontWeight: 500,
                color: "#667085",
                background: "rgba(102,112,133,0.12)",
              }}
