              {row.role}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * Animated ring that draws itself around a UI region — a rounded rect or a
 * circle — with an optional feathered dim-spotlight over everything else.
 * Transparent by default: layer it above a screenshot or a scene and point
 * it at the region you want the viewer to look at.
 */
export function HighlightRing({
  shape = "rect",
  rect,
  circle,
  radius = 8,
  strokeWidth = 2,
  color = "#266DF0",
  padding = 6,
  drawDuration = 12,
  pulse = false,
  dimOutside = false,
  dimColor = "rgba(10,10,11,0.45)",
  dimFeather = 24,
  enterAt = 0,
  exitAt = 0,
  speed = 1,
  showDemoUi = false,
  className,
}: HighlightRingProps) {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  // Stable per-instance SVG ids; sanitized for use in url(#…) references.
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const local = (frame - enterAt) * speed;
  const visible = local >= 0;

  const rectTarget = parseRect(rect, DEFAULT_RECT);
  const circleTarget = parseCircle(circle, DEFAULT_CIRCLE);

  // Ring bounding box: the target expanded by `padding` on every side.
  const box =
    shape === "circle"
      ? {
          x: circleTarget.cx - circleTarget.r - padding,
          y: circleTarget.cy - circleTarget.r - padding,
          w: (circleTarget.r + padding) * 2,
          h: (circleTarget.r + padding) * 2,
        }
      : {
          x: rectTarget.x - padding,
          y: rectTarget.y - padding,
          w: rectTarget.w + padding * 2,
          h: rectTarget.h + padding * 2,
        };

  const cornerRadius =
    shape === "circle" ? box.w / 2 : clampCornerRadius(radius, box.w, box.h);
  const pathLength =
    shape === "circle"
      ? circlePerimeter(box.w / 2)
      : roundedRectPerimeter(box.w, box.h, cornerRadius);

  // Stroke-dash draw, ease-out. Also gates the scrim fade-in.
  const drawProgress = interpolate(local, [0, drawDuration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  // Fade-out once `exitAt` is reached; 0 disables the exit entirely.
  const exitOpacity =
    exitAt > 0
      ? interpolate((frame - exitAt) * speed, [0, EXIT_FADE_FRAMES], [1, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.cubic),
        })
      : 1;

  // One subtle pulse right after the draw lands. High-damping feel, no loop.
  const pulseScale = pulse
    ? interpolate(
        local,
        [drawDuration, drawDuration + 8, drawDuration + 18],
        [1, 1.03, 1],
        {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.inOut(Easing.quad),
        },
      )
    : 1;

  // Stroke margin so the line is never clipped by the inner SVG viewport.
  const m = strokeWidth;

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
    >
      {showDemoUi && <AcmeSettingsDemo />}

      {visible && dimOutside && (
        <svg
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          style={{
            position: "absolute",
            inset: 0,
            opacity: drawProgress * exitOpacity,
          }}
          aria-hidden
        >
          <defs>
            <filter
              id={`${uid}-feather`}
              x="-50%"
              y="-50%"
              width="200%"
              height="200%"
            >
              <feGaussianBlur stdDeviation={dimFeather / 2} />
            </filter>
            <mask id={`${uid}-hole`}>
              <rect width={width} height={height} fill="#FFFFFF" />
              {shape === "circle" ? (
                <circle
                  cx={circleTarget.cx}
                  cy={circleTarget.cy}
                  r={circleTarget.r + padding}
                  fill="#000000"
                  filter={`url(#${uid}-feather)`}
                />
              ) : (
                <rect
                  x={box.x}
                  y={box.y}
                  width={box.w}
                  height={box.h}
                  rx={cornerRadius}
                  fill="#000000"
                  filter={`url(#${uid}-feather)`}
                />
              )}
            </mask>
          </defs>
          <rect
            width={width}
            height={height}
            fill={dimColor}
            mask={`url(#${uid}-hole)`}
          />
        </svg>
      )}

      {visible && (
        <div
          style={{
            position: "absolute",
            left: box.x - m,
            top: box.y - m,
            width: box.w + m * 2,
            height: box.h + m * 2,
            scale: pulseScale,
            opacity: exitOpacity,
          }}
        >
          <svg
            width={box.w + m * 2}
            height={box.h + m * 2}
            viewBox={`0 0 ${box.w + m * 2} ${box.h + m * 2}`}
            aria-hidden
          >
            {shape === "circle" ? (
              <circle
                cx={m + box.w / 2}
                cy={m + box.h / 2}
                r={box.w / 2}
                fill="none"
                stroke={color}
                strokeWidth={strokeWidth}
                strokeLinecap="round"
                strokeDasharray={pathLength}
                strokeDashoffset={pathLength * (1 - drawProgress)}
              />
            ) : (
              <rect
                x={m}
                y={m}
                width={box.w}
                height={box.h}
                rx={cornerRadius}
                fill="none"
                stroke={color}
                strokeWidth={strokeWidth}
                strokeLinecap="round"
                strokeDasharray={pathLength}
                strokeDashoffset={pathLength * (1 - drawProgress)}
              />
            )}
          </svg>
        </div>
      )}
    </div>
  );
}
